Translate the following GNU C++ code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to translate:
<original_code>
#include <cstdio>
#include <cstring>
#include <algorithm>
using namespace std;

const int MAXN=300010;
int n, K, mod;
int dp[MAXN][20];
int countArr[MAXN], maxBit[MAXN];
int comb[MAXN], invComb[MAXN];

int fastPower(int base, int exp) {
    int result=1;
    while (exp > 0) {
        if (exp & 1) result = (long long)result * base % mod;
        base = (long long)base * base % mod;
        exp >>= 1;
    }
    return result;
}

int combination(int i, int j) {
    return (long long)comb[i] * invComb[j] % mod * invComb[i - j] % mod;
}

int main() {
    scanf("%d%d%d", &n, &K, &mod);
    int i, j, k;
    int answer=0;
    int mask, remaining, temp, current, c1, c2;

    if (n & 1) {
        printf("%d\n", fastPower(K, n));
        return 0;
    }

    comb[0]=1;
    for (i=1; i<=n; i++) comb[i] = (long long)comb[i-1]*i % mod;

    invComb[n] = fastPower(comb[n], mod-2);
    invComb[0] = 1;
    for (i=n-1; i>=1; i--) invComb[i] = (long long)invComb[i+1]*(i+1) % mod;

    for (i=1; i<=n; i++) {
        for (j=0; j<=18; j++) {
            if ((1<<j) & i) countArr[i]++;
        }
    }

    for (i=1; i<=n; i++) {
        for (j=18; j>=0; j--) {
            if ((1<<j) & i) {
                maxBit[i] = 1<<j;
                break;
            }
        }
    }

    memset(dp, 0, sizeof(dp));
    dp[0][0] = 1;

    for (i=1; i<=n; i++) {
        if ((n & i) != i) continue;
        remaining = i ^ maxBit[i];
        for (mask=remaining; ; mask=(mask-1)&remaining) {
            current = mask + maxBit[i];
            c2 = i ^ current;
            int limit = min(K-1, countArr[c2]);
            int tmp = combination(i, current);
            for (j=0; j<=limit; j++) {
                dp[i][j+1] = (dp[i][j+1] + (long long)dp[c2][j] * tmp) % mod;
            }
            if (mask == 0) break;
        }
    }

    for (j=1; j<=min(countArr[n], K); j++) {
        answer = (answer + (long long)dp[n][j] * combination(K, j) % mod * comb[j]) % mod;
    }

    answer = (fastPower(K, n) - answer + mod) % mod;
    printf("%d\n", answer);
    return 0;
}
